#!/usr/bin/env python3
"""Independent changed-scope probes. No author regression helpers or old suites.
Run all once, or reproduce one: python3 -I FILE --case CASE_NAME.
Writes results only beside this file; does not execute a model, scorer or evaluator.
"""
from copy import deepcopy
import hashlib
import json
from pathlib import Path
import runpy
import sys
import traceback

sys.dont_write_bytecode = True
ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent

def pack(x):
    return json.dumps(x, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()

def digest(x):
    return hashlib.sha256(x).hexdigest()

def load(p):
    return json.loads((ROOT / p).read_text())

checker = runpy.run_path(str(ROOT / 'benchmark/verify_attempt_evidence_0143.py'))
group = runpy.run_path(str(ROOT / 'benchmark/verify_project_run_binding_0138.py'))
legacy = group['load_legacy_functions']()
data = load('benchmark/attempt-evidence-0143.json')
base = data['fixture']
source = {'base': load('benchmark/project-run-binding-0138.json')['rehearsal']['fixture'],
          'template': load('benchmark/baseline/run-record.template.json')}
source['manifest'] = json.loads(source['base']['manifest_text'])
plan = json.loads(source['base']['plan_text'])
original_inventory = source['base']['source_inventory']['original_artifact_set_and_hashes']
assert len(original_inventory) == 1, 'Pinned scope is one original; no generalized inventory claim'
assert len(plan['slots']) == 2 and len(plan['comparisons']) == 1
assert len(base['envelope']['attempts']) == 2
expected_inputs = [{'kind': 'synthetic:original', 'identity': 'synthetic:original-1',
                    'sha256': original_inventory[0]['sha256']}]
for a in base['envelope']['attempts']:
    assert a['legacy_record']['fields']['input_evidence']['value'] == expected_inputs
    for k in legacy['UNDECIDED']:
        assert a['legacy_record']['fields'][k] == source['template']['fields'][k]

def attempts(f):
    return f['envelope']['attempts']

def arm(f, name='tool'):
    return next(a for a in attempts(f) if a['arm'] == name)

def fields(f, name='tool'):
    return arm(f, name)['legacy_record']['fields']

def evidence(a, kind):
    return next(e for e in a['evidence'] if e['kind'] == kind)

def raw(f, a, kind):
    e = evidence(a, kind)
    return None if e['presence'] == 'absent' else bytes.fromhex(f['payloads'][e['payload_ref']]['hex'])

def replace_payload(f, a, kind, value):
    ref = 'synthetic:payload-review-' + str(len(f['payloads']))
    f['payloads'][ref] = {'encoding': 'hex', 'hex': value.hex(), 'byte_size': len(value),
                          'sha256': digest(value), 'utf8': value.decode('utf-8')}
    e = evidence(a, kind)
    e['payload_ref'] = ref
    e['presence'] = 'present'

def contrad(f, name, what):
    v = fields(f, name)
    if what == 'model':
        v['model_identity']['value'] = 'synthetic:independent-wrong-model-0146'
    elif what == 'prompt':
        v['common_prompt_sha256']['value'] = digest(b'SYNTHETIC independent wrong common prompt')
    else:
        inv = v['input_evidence']['value']
        if what in ('identity', 'kind'):
            inv[0][what] = 'synthetic:independent-wrong-' + what
        elif what == 'hash':
            inv[0]['sha256'] = digest(b'SYNTHETIC independent wrong original')
        elif what == 'omitted':
            inv.clear()
        elif what == 'extra':
            extra = deepcopy(inv[0]); extra['identity'] = 'synthetic:original-extra'; inv.append(extra)
        elif what == 'duplicate':
            inv.append(deepcopy(inv[0]))
        else:
            raise AssertionError(what)

def four_joins(f):
    for what in ('model', 'prompt', 'hash'):
        contrad(f, 'tool', what)
    fields(f)['tool_calls']['value'][0]['response'] = 'SYNTHETIC independent wrong response'

def duplicate_slots(f):
    for old in list(attempts(f)):
        a = deepcopy(old)
        ev = json.loads(raw(f, old, 'attempt_event'))
        a['attempt_id'] += '-independent-copy'
        a['attempt_order'] = len(attempts(f)) + 1
        for e in a['evidence']:
